function recipeWrapPrompt(text){
  const format=getVal('Prompt Recipe Output Format');
  // Keep output compact by default. Recipe mode now creates a short prompt recipe, not a long document.
  if(!format || format===NONE || /Standard clean/i.test(format)) return text;
  const source=cleanupPromptText(text).split('\n').filter(Boolean);
  const pick=(rx,limit)=>source.filter(l=>rx.test(l)).slice(0,limit).join('\n');
  if(/Short copy/i.test(format)){
    return cleanupPromptText(source
      .filter(line=>!/ACTIVE:|output format selected|rule:/i.test(line))
      .slice(0,28)
      .join('\n'));
  }
  if(/Recipe sections|section labels|Detailed premium/i.test(format)){
    return cleanupPromptText([
      'PROMPT RECIPE OUTPUT - COMPACT',
      'SUBJECT: '+pick(/plus-size|character|ethnicity|skin tone|body type|pose|expression/i,4),
      'HAIR/BEAUTY: '+pick(/hair|makeup|nails|tattoo|jewelry|accessor/i,5),
      'OUTFIT/PROPS: '+pick(/outfit|top style|bottom style|shirt|sleeve|prop|tumbler|mockup|product|etsy/i,5),
      'TYPOGRAPHY: '+pick(/typography|text|headline|affirmation|font|readable|word|quote/i,4),
      'SCENE/LIGHTING: '+pick(/scene|background|lighting|camera|composition|environment|motion|glow|color palette/i,5),
      'QUALITY: '+pick(/quality|no |avoid|do not|final finish|priority|platform|toggle/i,4)
    ].filter(Boolean).join('\n'));
  }
  return text;
}
