function getControlCategory(name) {
  const n = String(name).toLowerCase();
  if (n.includes('preset') || n.includes('aspect') || n.includes('art style') || n.includes('palette') || n.includes('lighting') || n.includes('camera') || n.includes('render') || n.includes('photo') || n.includes('dna') || n.includes('platform')) return 'style';
  if (n.includes('ethnicity') || n.includes('skin') || n.includes('body') || n.includes('hair') || n.includes('makeup') || n.includes('nail') || n.includes('tattoo') || n.includes('face') || n.includes('pose') || n.includes('character') || n.includes('expression')) return 'model';
  if (n.includes('outfit') || n.includes('top') || n.includes('bottom') || n.includes('shoe') || n.includes('accessor') || n.includes('coverage') || n.includes('dress') || n.includes('heel') || n.includes('wardrobe')) return 'fashion';
  if (n.includes('background') || n.includes('scene') || n.includes('car') || n.includes('vehicle') || n.includes('plate') || n.includes('mirror') || n.includes('reflection') || n.includes('room') || n.includes('environment') || n.includes('vanity')) return 'scene';
  if (n.includes('decor') || n.includes('butterfly') || n.includes('sparkle') || n.includes('crystal') || n.includes('moon') || n.includes('blend') || n.includes('depth') || n.includes('flow') || n.includes('hand') || n.includes('particle') || n.includes('motion') || n.includes('glow')) return 'effects';
  return 'typo';
}

