function fallbackCopy(text){
  const ta=document.createElement('textarea');
  ta.value=text;
  ta.style.position='fixed';
  ta.style.left='-9999px';
  document.body.appendChild(ta);
  ta.select();
  document.execCommand('copy');
  document.body.removeChild(ta);
  if(typeof showToast === 'function') showToast('Copied to clipboard!', '📋');
  else alert('Copied clean text ✅');
}

function copyText(id){
  const el=document.getElementById(id);
  if(!el) return;
  const text=(el.value!==undefined?el.value:el.innerText||el.textContent||'').trim();
  if(!text) {
    if(typeof showToast === 'function') showToast('Nothing to copy yet. Generate something first!', '⚠️');
    else alert('Nothing to copy yet. Generate something first.');
    return;
  }
  if(navigator.clipboard && navigator.clipboard.writeText) {
    navigator.clipboard.writeText(text).then(()=>{
      if(typeof showToast === 'function') showToast('Copied to clipboard!', '📋');
      else alert('Copied clean text ✅');
    }).catch(()=>fallbackCopy(text));
  } else {
    fallbackCopy(text);
  }
}

function savePrompt(){
  const promptEl = document.getElementById('promptOut');
  const historyEl = document.getElementById('history');
  if(!promptEl || !historyEl) return;
  const promptVal = promptEl.value.trim();
  if(!promptVal) {
    if(typeof showToast === 'function') showToast('Generate a prompt first before saving!', '⚠️');
    else alert('Generate a prompt first before saving!');
    return;
  }
  
  const div = document.createElement('div');
  div.className = 'history-item-card';
  div.style.cssText = 'background: rgba(2, 6, 23, 0.85); border: 1px solid rgba(245, 208, 97, 0.3); border-radius: 10px; padding: 12px; margin: 10px 0; display: flex; flex-direction: column; gap: 8px;';
  
  const timeStr = new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' });
  const themeName = activeTab || 'Main Generator';
  
  div.innerHTML = `
    <div style="display: flex; justify-content: space-between; align-items: center; border-bottom: 1px solid rgba(255,255,255,0.1); padding-bottom: 6px;">
      <span style="font-size: 11px; font-weight: 700; color: var(--gold-primary); text-transform: uppercase;">${themeName} · ${timeStr}</span>
      <div style="display: flex; gap: 6px;">
        <button type="button" class="btn-gen-sec" style="padding: 3px 8px; font-size: 11px;" onclick="copyHistoryCard(this)">📋 Copy</button>
        <button type="button" class="btn-gen-sec" style="padding: 3px 8px; font-size: 11px;" onclick="loadHistoryCard(this)">Load</button>
      </div>
    </div>
    <div class="history-content-text" style="font-size: 12px; color: #f1f5f9; line-height: 1.5; white-space: pre-wrap; max-height: 160px; overflow-y: auto;">${promptVal.replace(/</g, '&lt;').replace(/>/g, '&gt;')}</div>
  `;
  
  historyEl.prepend(div);
  
  try {
    const raw = localStorage.getItem('psbg_prompt_history');
    const list = raw ? JSON.parse(raw) : [];
    list.unshift({ tab: themeName, prompt: promptVal, time: new Date().toISOString() });
    if(list.length > 40) list.pop();
    localStorage.setItem('psbg_prompt_history', JSON.stringify(list));
  } catch(e) {
    console.warn('History storage failed', e);
  }
  
  if(typeof showToast === 'function') {
    showToast('Saved to History! Check History tab.', '💾');
  } else {
    alert('Saved to History! ✅');
  }
}

function copyHistoryCard(btn) {
  const card = btn.closest('.history-item-card');
  const textEl = card ? card.querySelector('.history-content-text') : null;
  const text = textEl ? textEl.textContent.trim() : '';
  if(!text) return;
  if(navigator.clipboard && navigator.clipboard.writeText) {
    navigator.clipboard.writeText(text).then(() => {
      if(typeof showToast === 'function') showToast('History prompt copied!', '📋');
      else alert('Copied clean text ✅');
    }).catch(() => fallbackCopy(text));
  } else {
    fallbackCopy(text);
  }
}

function loadHistoryCard(btn) {
  const card = btn.closest('.history-item-card');
  const textEl = card ? card.querySelector('.history-content-text') : null;
  const text = textEl ? textEl.textContent.trim() : '';
  if(!text) return;
  const promptEl = document.getElementById('promptOut');
  if(promptEl) {
    promptEl.value = text;
    if(typeof switchStudioTab === 'function') {
      const promptBtn = document.querySelector('[data-studio="studio-prompt"]');
      switchStudioTab('studio-prompt', promptBtn);
    }
    if(typeof showToast === 'function') showToast('Loaded into Prompt Studio!', '💎');
  }
}

function loadStoredHistory() {
  const historyEl = document.getElementById('history');
  if(!historyEl) return;
  try {
    const raw = localStorage.getItem('psbg_prompt_history');
    if(!raw) return;
    const list = JSON.parse(raw);
    if(Array.isArray(list) && list.length) {
      list.slice(0, 30).forEach(item => {
        if(!item || !item.prompt) return;
        const div = document.createElement('div');
        div.className = 'history-item-card';
        div.style.cssText = 'background: rgba(2, 6, 23, 0.85); border: 1px solid rgba(245, 208, 97, 0.3); border-radius: 10px; padding: 12px; margin: 10px 0; display: flex; flex-direction: column; gap: 8px;';
        const dateStr = item.time ? new Date(item.time).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' }) : '';
        div.innerHTML = `
          <div style="display: flex; justify-content: space-between; align-items: center; border-bottom: 1px solid rgba(255,255,255,0.1); padding-bottom: 6px;">
            <span style="font-size: 11px; font-weight: 700; color: var(--gold-primary); text-transform: uppercase;">${item.tab || 'Main'} ${dateStr ? '· ' + dateStr : ''}</span>
            <div style="display: flex; gap: 6px;">
              <button type="button" class="btn-gen-sec" style="padding: 3px 8px; font-size: 11px;" onclick="copyHistoryCard(this)">📋 Copy</button>
              <button type="button" class="btn-gen-sec" style="padding: 3px 8px; font-size: 11px;" onclick="loadHistoryCard(this)">Load</button>
            </div>
          </div>
          <div class="history-content-text" style="font-size: 12px; color: #f1f5f9; line-height: 1.5; white-space: pre-wrap; max-height: 160px; overflow-y: auto;">${String(item.prompt).replace(/</g, '&lt;').replace(/>/g, '&gt;')}</div>
        `;
        historyEl.appendChild(div);
      });
    }
  } catch(e) {
    console.warn('Could not load stored history', e);
  }
}

