function mirrorSetField(k,v){
  const el=document.getElementById(idFor(k));
  if(!el||locked(k)||!v) return;
  const has=[...el.options].some(o=>o.value===v);
  if(has) el.value=v;
}
function mirrorApplyPresetMap(preset){
  if(!activeTab.includes('Mirror')) return;
  const map=MIRROR_PRESET_MAP[preset]||{};
  Object.entries(map).forEach(([k,v])=>mirrorSetField(k,v));
  saveActiveTabState();
}
function mirrorSmartRandom(){
  if(!activeTab.includes('Mirror')) return;
  const presetEl=document.getElementById(idFor('Preset'));
  const presets=Object.keys(MIRROR_PRESET_MAP);
  const preset=presetEl && !locked('Preset') ? rand(presets) : (presetEl?.value||rand(presets));
  if(presetEl && !locked('Preset')) presetEl.value=preset;
  mirrorApplyPresetMap(preset);
  const safeFill=['Hair / Hairstyle','Makeup','Nails','Tattoos','Tattoo Placement','Accessories','Shoes','Outfit Coverage / Style Mode','Affirmation Text','Quote Style','Mirror Headline Word','Reflection Quote Style','Mirror Text Placement','Reflection Tears / Healing Effects','Mirror Crack / Glow Details','Vanity / Room Props','Reflection Transformation Stage','Main Self Styling Mood','Before vs After Symbol Details','Final Mirror Quality Rule','Luxury Vanity Scene','Bedroom / Closet / Bathroom Expansion','Dreamy Cloud Mirror Rooms','Broken-to-Healed Environment Shift','Lighting Mood Expansion','Mirror Frame Styles','Background Detail Expansion','Foreground Vanity Props','Reflection Fog / Smoke / Sparkle Effects','Scene Blend Rule'];
  safeFill.forEach(k=>{
    const el=document.getElementById(idFor(k));
    if(!el||locked(k)) return;
    let opts=[...el.options].map(o=>o.value).filter(v=>v!==NONE);
    if(churchModeOn()&&(k==='Outfit Coverage / Style Mode'||k.includes('Outfit'))) opts=opts.filter(v=>!isUnsafeChurchValue(v));
    if(opts.length) el.value=rand(opts);
  });
  mirrorSetField('Mirror Blend Rule','Main self, reflection, mirror glow, smoke, typography, and room lighting must feel like one cohesive emotional scene');
  mirrorSetField('Text Placement Safety','No text over face, reflection face, body, hands, or mirror focal point; keep words large and readable');
  mirrorSetField('No Horror / No Creepy Rule','No horror, no possession, no scary faces, no haunted mirror, no demonic mood; keep it emotional, healing, glamorous, and beautiful');
  applyChurchModeOverrides();
  saveActiveTabState();
  generatePrompt();
}
